"""Embed web/assets/models/worker.glb as base64 JS so the UI can load it from file://."""
import base64
from pathlib import Path

root = Path(__file__).resolve().parents[1]
src = root / "web/assets/models/worker.glb"
dst = root / "web/assets/models/worker_glb.js"
payload = base64.b64encode(src.read_bytes()).decode("ascii")
dst.write_text(
    "// Generated by scripts/embed_model.py — do not edit.\n"
    f'window.ECHO_WORKER_GLB = "{payload}";\n',
    encoding="utf-8",
)
print(f"{src} -> {dst} ({dst.stat().st_size / 1e6:.1f} MB)")
